double integral = 0.0;
    double h = b - a;
    double fa = f(a);
    double fb = f(b);
    double initial_estimate = 0.5 * h * (fa + fb);
    std::stack<std::tuple<double, double, double, double, double>> intervals;
    intervals.push(std::make_tuple(a, b, fa, fb, initial_estimate));

    while (!intervals.empty()) {
        auto [current_a, current_b, current_fa, current_fb, current_estimate] = intervals.top();
        intervals.pop();
        double current_h = current_b - current_a;
        double c = 0.5 * (current_a + current_b);
        double fc = f(c);
        double left_estimate = 0.5 * (c - current_a) * (current_fa + fc);
        double right_estimate = 0.5 * (current_b - c) * (fc + current_fb);
        double refined_estimate = left_estimate + right_estimate;

        if (std::abs(refined_estimate - current_estimate) <= 15 * precision * current_h / h) {
            integral += refined_estimate;
        } else {
            intervals.push(std::make_tuple(c, current_b, fc, current_fb, right_estimate));
            intervals.push(std::make_tuple(current_a, c, current_fa, fc, left_estimate));
        }
    }

    return integral;
